function renderOverview(facts, claims) {
  const components = [...new Set(facts.map((fact) => fact.component))].sort();
  const rows = components.map((name) => {
    const files = facts.filter((fact) => fact.component === name);
    const symbols = files.reduce((sum, fact) => sum + fact.symbols.length, 0);
    return `| ${name} | ${files.length} | ${symbols} |`;
  });
  return [
    "# Architecture Overview",
    "",
    "Generated by `xfeat scan` from repository source evidence.",
    "",
    `- Source files: ${facts.length}`,
    `- Grounded claims: ${claims.length}`,
    "",
    "| Component | Files | Symbols |",
    "| --- | ---: | ---: |",
    ...rows,
    "",
    "## Claim Evidence",
    "",
    "| Claim | Source |",
    "| --- | --- |",
    ...claims.slice(0, 25).map((claim) => {
      const source = `${claim.file}:${claim.line}`;
      return `| ${claim.text} | \`${source}\` |`;
    }),
    "",
  ].join("\n");
}

function renderComponent(name, facts) {
  const lines = [`# Component: ${name}`, "", "## Source Files", ""];
  for (const fact of facts) {
    lines.push(`### \`${fact.file}\``, "");
    lines.push(`- Lines: ${fact.lineCount}`);
    if (fact.symbols.length === 0) {
      lines.push("- Symbols: none detected");
    } else {
      lines.push("- Symbols:");
      for (const symbol of fact.symbols) {
        lines.push(
          `  - \`${symbol.name}\` (${symbol.type}) at \`${fact.file}:${symbol.line}\``,
        );
      }
    }
    lines.push("");
  }
  return lines.join("\n");
}

function renderOnboarding(facts) {
  const topFiles = facts.slice(0, 12).map((fact) => `- \`${fact.file}\``);
  return [
    "# Onboarding Map",
    "",
    "Start with the architecture overview, then inspect component pages by area.",
    "",
    "## First Files To Read",
    "",
    ...topFiles,
    "",
    "## Review Checklist",
    "",
    "- Confirm component ownership before changing behavior.",
    "- Run `xfeat audit --changed` before merging documentation changes.",
    "- Run `xfeat verify` after regenerating docs.",
    "",
  ].join("\n");
}

function renderAdrIndex(markdownFiles) {
  const adrFiles = markdownFiles.filter((file) =>
    /(^|\/)adr[-_]?|architecture-decision/i.test(file),
  );
  const rows = adrFiles.length
    ? adrFiles.map((file) => `- [${file}](../${file})`)
    : ["- No ADR files detected yet."];
  return [
    "# ADR Index",
    "",
    "Architecture decision records found in this repository.",
    "",
    ...rows,
    "",
  ].join("\n");
}

function renderReport(facts, claims, docs) {
  return [
    "# xfeat Report",
    "",
    `- Source files: ${facts.length}`,
    `- Grounded claims: ${claims.length}`,
    `- Documents: ${docs.length}`,
    "",
  ].join("\n");
}

module.exports = {
  renderOverview,
  renderComponent,
  renderOnboarding,
  renderAdrIndex,
  renderReport,
};
